const LanguageContext = createContext({
  lang: 'vi',
  setLang: () => {},
  t: (key, fallback) => fallback || key,
});

export function LanguageProvider({ children }) {
  const branchCtx = useBranch();
  const branchLang = branchCtx?.currentBranch?.language || 'vi';

  const [lang, setLang] = useState(() => branchLang);

  useEffect(() => {
    if (branchLang) {
      setLang(branchLang);
    }
  }, [branchLang]);

  useEffect(() => {
    if (typeof window !== 'undefined') localStorage.setItem('app_lang', lang);
  }, [lang]);

  const t = (key, fallback, params) => {
    let res = translations[lang]?.[key] || translations.en?.[key] || fallback || key;
    if (params && typeof params === 'object') {
      Object.keys(params).forEach(pKey => {
        res = res.replace(new RegExp(`\\{${pKey}\\}`, 'g'), params[pKey]);
      });
    }
    return res;
  };

  return (
    <LanguageContext.Provider value={{ lang, setLang, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useT() {
  const ctx = useContext(LanguageContext);
  const translateFn = ctx?.t || ((k, f, p) => {
    let res = f || k;
    if (p && typeof p === 'object') {
      Object.keys(p).forEach(pKey => {
        res = res.replace(new RegExp(`\\{${pKey}\\}`, 'g'), p[pKey]);
      });
    }
    return res;
  });

  const fn = (key, fallback, params) => translateFn(key, fallback, params);
  fn.t = translateFn;
  fn.lang = ctx?.lang || 'vi';
  fn.setLang = ctx?.setLang || (() => {});
  return fn;
}